def reserve(self, request: DisclosureRequest, grant) -> AnnotationRequestsRow:
    key = self.address(request.span, request.question, request.classifier)
    with self.session.transaction() as db:
        if AnnotationRequestsRow.one(db, **key) is not None:
            raise PreviouslyRequestedAnnotation('Original classifier request already recorded; inspect its disposition')
        now = self.session.now()
        grant.require_budget(AnnotationRequestsRow.requests_since(db, request.grant, grant.window_start(now)))
        original = AnnotationRequestsRow(request=request, outcome=SubmittedAnnotationOutcome(), created_at_ms=now)
        sequence = original.insert(db).lastrowid
        return AnnotationRequestsRow.one(db, id=sequence)

@staticmethod
def reserve(*, owner, comms, autonomous):
    try:
        store = comms.goals.open_goal_store()
        admission = comms.registry.snapshot().admission_generations[owner.name]
        with _store_lock(comms._wire_lock_path):
            generation = store.require_generation(owner.goal.id)
            generation.lifecycle.require_ready()
            grant = comms.goals.ready_goal_grant_locked(owner, admission, generation)
            reservation = store.reserve(owner.goal.id, generation.number, ready_grant=grant)
            return store.claim_launch(reservation)
    except GoalAttemptError as error:
        if autonomous:
            return None
        raise RequestError.invalid_params({'reason': 'goal_attempt_unavailable', 'details': 'The goal has no launchable attempt. Inspect its state and use Retry for a failed attempt; no prompt was sent to Pi.'}) from error

