def reserve(self, dispositions: InputDispositions, owner: Thread, turn: TurnId, admission: int, *, custody: ExitStack) -> OriginalTurnInput:
    """Every original uses the same durable input authority before native preparation.

        ACP and bus inputs already own ingress keys. A scheduled original has no
        external ingress; its admitted turn supplies identity, never replay authority.
        """
    if self.keys:
        return self
    batch = dispositions.reserve_turn(owner.name, turn, admission, self.prompt, custody=custody)
    return replace(self, batch=batch)

