@classmethod
def capture(cls, connection: sqlite3.Connection, sources: Sequence[CommittedDelivery]) -> NotificationAssignmentRead:
    """Capture detached assignment evidence for one bounded window of originals
        from the caller's SQLite snapshot."""
    from .presentation import MessageNotification
    sources = tuple(sources)
    if len(sources) > MessageNotification.window_limit:
        raise ValueError('Notification reads require a bounded visible message window')
    if not sources:
        return NotificationAssignmentRead((), ())
    from .coordination_tables.executions import CurrentExecutions
    from .native_input_record import TriageNativeExecution
    from .native_runtime_input import NativeRuntimeInput
    if SQLiteUserVersion.read(connection.execute('PRAGMA user_version')) != [SQLiteUserVersion(COORDINATION_SCHEMA_VERSION)]:
        raise ValueError('Channel notification status has an unsupported schema')
    columns = ','.join((f'w.{name}' for name in WakeAssignment.columns()))
    triage_stage = sql_literal(TriageNativeExecution)
    rows = WakeAssignment.joined(connection.execute(f"WITH w AS MATERIALIZED (SELECT * FROM {WakeAssignment.declared_name} WHERE wire_seq IN ({','.join(('?' for _ in sources))})), member AS MATERIALIZED (SELECT m.input_id,m.assignment_id,m.ordinal FROM ({NativeRuntimeInput.source_membership_sql()}) m WHERE m.assignment_id IN (SELECT assignment_id FROM w)) SELECT {columns}, EXISTS (SELECT 1 FROM {NativeRuntimeInput.declared_name} n JOIN member ON member.input_id=n.input_id WHERE member.assignment_id=w.assignment_id AND n.stage={triage_stage} AND n.session_entry_id IS NULL) AS triage_inflight, pointer.execution_id AS current_execution_id, (SELECT n.committed_at_ms FROM {NativeRuntimeInput.declared_name} n JOIN member ON member.input_id=n.input_id WHERE member.assignment_id=w.assignment_id AND n.session_entry_id IS NOT NULL ORDER BY CASE n.stage WHEN {triage_stage} THEN 0 ELSE 1 END,member.ordinal,n.input_id LIMIT 1) AS context_committed_at_ms, p.seq AS response_seq, p.message_id AS response_message_id, p.received_at_ms AS response_received_at_ms FROM w LEFT JOIN {CurrentExecutions.declared_name} pointer ON pointer.owner_lookup=w.recipient_lookup LEFT JOIN {PublicationReceipts.declared_name} p ON p.execution_id=w.execution_id AND p.exact_target=w.exact_target ORDER BY w.wire_seq DESC,w.recipient", tuple((source.message.seq for source in sources))), AssignmentActivityEvidence)
    return NotificationAssignmentRead(sources, tuple(rows))

@classmethod
def capture(cls, comms: Comms, admission: AdmissionIdentity) -> HumanInputOrigin:
    from .active_route import guard_original_root_write
    from .store_files import _store_lock
    with guard_original_root_write(comms.root), _store_lock(comms._wire_lock_path):
        snapshot = comms.registry.snapshot()
        owner = snapshot.require_active(admission.incarnation.name)
        if snapshot.admission_identity(owner.name) != admission:
            raise RelationViolationError('User input attachment changed before capture')
        root_id = comms.bus.log.read_metadata_unlocked().wire_root_id
        root_id = WireRootIdText.decode(root_id)
        user = comms.messaging._user_identity_under_wire_lock(owner.worktree)
        return cls(root_id, HumanOrigin(user.name, user.created_at, user.worktree), admission, owner.worktree, owner.goal_checkpoint)

