@classmethod
def capture(cls, owner, relations, goals):
    """The most recent goal change of each peer whose relevance keeps ``owner`` informed."""
    changes = tuple((change for relation in relations if relation.relevance.grants(Informed) for change in (PartnerGoalChange.latest(relation.peer.name, goals.goal_history(relation.peer.name)),) if change is not None))
    if not changes:
        return ()
    changes = tuple(sorted(changes, key=lambda change: change.observed_at)[-cls.LATEST:])
    instruction = InstructionFile.read('partner-activity.md')
    revision = hashlib.sha256(json.dumps(FieldCodec.encode(changes)).encode()).hexdigest()
    return (cls(provenance=(instruction.source, OwnerProvenance(owner.incarnation, revision)), instruction=instruction, changes=changes),)

