@classmethod
def capture(cls, owner, relations):
    """Every relation ``owner`` has, in the order its peers are listed."""
    records = tuple((record for relation in relations for record in relation.records))
    if not records:
        return ()
    instruction = InstructionFile.read('relationships.md')
    revision = hashlib.sha256(json.dumps(FieldCodec.encode(records)).encode()).hexdigest()
    return (cls(provenance=(instruction.source, OwnerProvenance(owner.incarnation, revision)), instruction=instruction, records=records),)

@classmethod
def capture(cls, retained: RetainedTaskFacts, owner, registry, boundary: WireExportBoundary) -> 'RetainedSegment':
    source = OwnerProvenance(owner.incarnation, retained.source_digest.value)
    sources = {message.reference: message for fact in retained.facts for message in fact.wire_sources()}
    wording_sources = tuple((message.task.original_wording_context_source(retained.original_text_source(message)) for message in sources.values()))
    return cls(provenance=tuple(dict.fromkeys((source, *(WireProvenance(ref) for ref in sources), *wording_sources))), retained=retained, boundary=boundary, scope=AuthoredSourceScope(tuple((message.reference for message in retained.current_authored_sources(owner, registry)))))

