@classmethod
def capture(cls, tree: 'ProjectDirectoryTree') -> 'ProjectTreeIntent':
    expanded: set[Path] = set()
    nodes = [tree.root]
    while nodes:
        node = nodes.pop()
        if node.data is not None and node.is_expanded:
            expanded.add(node.data.path)
            nodes.extend(node.children)
    selected = tree.cursor_node
    return cls(Path(tree.path), frozenset(expanded), selected.data.path if selected is not None and selected.data is not None else None, tree.scroll_offset)
